223	            let mut split_ix = cmp::min(chunk::MAX_BASE, text.len());
224	            while !text.is_char_boundary(split_ix) {
225	                split_ix -= 1;
226	            }
227	            let (chunk, remainder) = text.split_at(split_ix);
228	            new_chunks.push(chunk);
229	            text = remainder;
230	        }
